import { useMemo, useState } from "react";
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ListFilter,
} from "lucide-react";
import { ClassificationStatusBadge } from "./shared";
import { SearchIcon } from "./icons";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  classificationQueue,
  type ClassificationRow,
  type ClassificationStatus,
} from "../../data";
import { cn } from "@/lib/utils";

type StatusFilter = "all" | ClassificationStatus;

const PAGE_SIZE = 6;

const filters: { value: StatusFilter; label: string }[] = [
  { value: "all", label: "All" },
  { value: "processing", label: "Processing" },
  { value: "needs-review", label: "Need Review" },
  { value: "approved", label: "Approved" },
];

export function ClassificationContent() {
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [page, setPage] = useState(1);

  const counts = useMemo(() => {
    return {
      all: classificationQueue.length,
      processing: classificationQueue.filter(
        (row) => row.status === "processing",
      ).length,
      "needs-review": classificationQueue.filter(
        (row) => row.status === "needs-review",
      ).length,
      approved: classificationQueue.filter((row) => row.status === "approved")
        .length,
    };
  }, []);

  const filteredRows = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();

    return classificationQueue.filter((row) => {
      const matchesStatus =
        statusFilter === "all" ? true : row.status === statusFilter;
      const matchesQuery =
        query === "" ||
        row.product.toLowerCase().includes(query) ||
        row.id.toLowerCase().includes(query) ||
        row.hsCode.toLowerCase().includes(query);

      return matchesStatus && matchesQuery;
    });
  }, [searchQuery, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filteredRows.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const pageStart = (currentPage - 1) * PAGE_SIZE;
  const pageRows = filteredRows.slice(pageStart, pageStart + PAGE_SIZE);

  const setFilter = (value: StatusFilter) => {
    setStatusFilter(value);
    setPage(1);
  };

  return (
    <div className="mx-auto flex w-full max-w-7xl flex-col gap-10 px-4 pt-8 pb-10 md:px-6">
      <div className="space-y-2">
        <h1 className="text-2xl font-semibold">Classification Queue</h1>
        <p className="text-lg text-muted-foreground">
          Review and manage AI-powered HS code classifications
        </p>
      </div>

      <div className="flex flex-col gap-5">
        <div className="flex flex-col gap-3 md:hidden">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2 text-sm font-medium">
              <ListFilter className="size-4" />
              Filters
            </div>

            <DropdownMenu>
              <DropdownMenuTrigger
                type="button"
                className="inline-flex min-w-28 shrink-0 items-center justify-between gap-2 rounded-lg bg-primary px-3 py-2.5 text-sm font-medium text-primary-foreground"
              >
                {filters.find((filter) => filter.value === statusFilter)?.label}
                <ChevronDown className="size-4 shrink-0" />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                collisionPadding={16}
                className="astrix-dashboard min-w-44"
              >
                <DropdownMenuRadioGroup
                  value={statusFilter}
                  onValueChange={(value) => setFilter(value as StatusFilter)}
                >
                  {filters.map((filter) => (
                    <DropdownMenuRadioItem
                      key={filter.value}
                      value={filter.value}
                      className="font-normal text-muted-foreground data-[state=checked]:font-medium data-[state=checked]:text-foreground"
                    >
                      {filter.label}
                      <span className="ml-auto text-xs tabular-nums">
                        {counts[filter.value]}
                      </span>
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          <InputGroup className="h-11 w-full border-none bg-secondary px-3 py-1">
            <InputGroupAddon className="pl-0">
              <SearchIcon className="size-3.5 text-input-addon-foreground" />
            </InputGroupAddon>
            <InputGroupInput
              className="h-full p-0 px-1.5!"
              aria-label="Search classifications"
              placeholder="Search products, HS codes, classifications..."
              value={searchQuery}
              onChange={(event) => {
                setSearchQuery(event.target.value);
                setPage(1);
              }}
            />
          </InputGroup>
        </div>

        <div className="@container/toolbar hidden w-full min-w-0 md:block">
          <div className="flex w-full min-w-0 flex-col gap-3 @min-[52rem]/toolbar:flex-row @min-[52rem]/toolbar:items-center @min-[52rem]/toolbar:justify-between">
            <InputGroup className="h-11 w-full border-none bg-secondary px-3 py-1 @min-[52rem]/toolbar:min-w-60 @min-[52rem]/toolbar:max-w-92.25 @min-[52rem]/toolbar:flex-1">
              <InputGroupAddon className="pl-0">
                <SearchIcon className="size-3.5 text-input-addon-foreground" />
              </InputGroupAddon>
              <InputGroupInput
                className="h-full p-0 px-1.5!"
                aria-label="Search classifications"
                placeholder="Search products, HS codes, classifications..."
                value={searchQuery}
                onChange={(event) => {
                  setSearchQuery(event.target.value);
                  setPage(1);
                }}
              />
            </InputGroup>

            <div className="flex w-full items-center gap-1 rounded-[calc(var(--radius)+0.125rem)] border bg-secondary p-0.5 @min-[52rem]/toolbar:w-auto">
              {filters.map((filter) => {
                const isActive = statusFilter === filter.value;

                return (
                  <button
                    key={filter.value}
                    type="button"
                    onClick={() => setFilter(filter.value)}
                    className={cn(
                      "inline-flex flex-1 items-center justify-center gap-2 rounded-lg px-3 py-2.5 text-sm font-medium whitespace-nowrap transition-colors @min-[52rem]/toolbar:flex-none",
                      isActive
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground",
                    )}
                  >
                    {filter.label}
                    <span
                      className={cn(
                        "inline-flex h-5.5 min-w-5.5 items-center justify-center rounded-sm px-2 text-xs font-medium",
                        isActive
                          ? "bg-background text-primary"
                          : "bg-background text-foreground",
                      )}
                    >
                      {counts[filter.value]}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <Table className="min-w-215">
          <colgroup>
            <col className="w-[32%]" />
            <col className="w-[16%]" />
            <col className="w-[14%]" />
            <col className="w-[20%]" />
            <col className="w-[18%]" />
          </colgroup>
          <TableHeader>
            <TableRow>
              <TableHead>Product</TableHead>
              <TableHead>HS Code</TableHead>
              <TableHead>Confidence</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Submitted</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {pageRows.map((row) => (
              <ClassificationRowItem key={row.id} row={row} />
            ))}
          </TableBody>
        </Table>

        <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <p className="text-sm text-muted-foreground">
            <span className="md:hidden">
              {pageRows.length} out of {filteredRows.length}
            </span>
            <span className="hidden md:inline">
              Showing {pageRows.length} of {filteredRows.length} result
              {filteredRows.length === 1 ? "" : "s"}
            </span>
          </p>

          <div className="flex w-full items-center justify-between md:w-auto md:justify-start md:gap-3">
            <div className="flex items-center">
              {getPageItems(currentPage, totalPages).map((item, index) => (
                <PageItem
                  key={`${item}-${index}`}
                  item={item}
                  currentPage={currentPage}
                  onSelect={setPage}
                />
              ))}
            </div>

            <div className="flex items-center gap-3">
              <Button
                type="button"
                variant="outline"
                size="icon-lg"
                className="size-10"
                aria-label="Previous page"
                disabled={currentPage <= 1}
                onClick={() => setPage((value) => Math.max(1, value - 1))}
              >
                <ChevronLeft className="size-5" />
              </Button>
              <Button
                type="button"
                variant="outline"
                size="icon-lg"
                className="size-10"
                aria-label="Next page"
                disabled={currentPage >= totalPages}
                onClick={() =>
                  setPage((value) => Math.min(totalPages, value + 1))
                }
              >
                <ChevronRight className="size-5" />
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function ClassificationRowItem({ row }: { row: ClassificationRow }) {
  return (
    <TableRow>
      <TableCell className="whitespace-normal">
        <div className="space-y-1">
          <p className="truncate font-medium">{row.product}</p>
          <p className="truncate text-xs text-muted-foreground">{row.id}</p>
        </div>
      </TableCell>
      <TableCell className="font-mono">{row.hsCode}</TableCell>
      <TableCell className="tabular-nums">{row.confidence}</TableCell>
      <TableCell>
        <ClassificationStatusBadge status={row.status} />
      </TableCell>
      <TableCell className="text-muted-foreground">{row.submitted}</TableCell>
    </TableRow>
  );
}

function PageItem({
  item,
  currentPage,
  onSelect,
}: {
  item: number | "ellipsis";
  currentPage: number;
  onSelect: (page: number) => void;
}) {
  if (item === "ellipsis") {
    return (
      <span className="flex size-10 items-center justify-center text-sm text-muted-foreground">
        ...
      </span>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onSelect(item)}
      className={cn(
        "flex size-10 items-center justify-center rounded-lg text-sm transition-colors",
        item === currentPage
          ? "border border-primary font-bold text-foreground"
          : "text-muted-foreground hover:text-foreground",
      )}
    >
      {item}
    </button>
  );
}

function getPageItems(current: number, total: number): (number | "ellipsis")[] {
  if (total <= 5) {
    return Array.from({ length: total }, (_, index) => index + 1);
  }

  if (current <= 2) {
    return [1, 2, "ellipsis", total - 1, total];
  }

  if (current >= total - 1) {
    return [1, 2, "ellipsis", total - 1, total];
  }

  return [1, "ellipsis", current, "ellipsis", total];
}

import {
  createContext,
  useContext,
  useMemo,
  useState,
  type AnchorHTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";

type DashboardNavigation = {
  pathname: string;
  navigate: (pathname: string) => void;
};

const DashboardNavigationContext = createContext<DashboardNavigation | null>(
  null,
);

export function DashboardNavigationProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [pathname, setPathname] = useState("/");
  const value = useMemo(
    () => ({ pathname, navigate: setPathname }),
    [pathname],
  );

  return (
    <DashboardNavigationContext.Provider value={value}>
      {children}
    </DashboardNavigationContext.Provider>
  );
}

export function useDashboardNavigation() {
  const context = useContext(DashboardNavigationContext);

  if (!context) {
    throw new Error(
      "useDashboardNavigation must be used within DashboardNavigationProvider",
    );
  }

  return context;
}

export function DashboardLink({
  href,
  onClick,
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }) {
  const { navigate } = useDashboardNavigation();

  function handleClick(event: MouseEvent<HTMLAnchorElement>) {
    onClick?.(event);

    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    ) {
      return;
    }

    event.preventDefault();
    navigate(href);
  }

  return <a href={href} onClick={handleClick} {...props} />;
}

import { useMemo, useState, type ComponentType, type SVGProps } from "react";
import {
  ArrowRight,
  Calendar,
  ClipboardList,
  FileText,
  FolderDown,
  ListFilter,
  Shield,
  Wallet,
} from "lucide-react";
import { ChevronDownIcon } from "./icons";
import { ReportStatusBadge } from "./shared";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  dateRangeOptions,
  generatedReports,
  reportTypes,
  type DateRange,
  type GeneratedReport,
  type ReportStatus,
  type ReportType,
} from "../../data";
import { cn } from "@/lib/utils";

type ReportTypeFilter = "all" | ReportType;
type ReportStatusFilter = "all" | ReportStatus;

type SvgIcon = ComponentType<SVGProps<SVGSVGElement>>;

const reportTypeIcons: Record<ReportType, SvgIcon> = {
  "cf-28": FileText,
  "cf-29": Wallet,
  "classification-audit": ClipboardList,
  "compliance-summary": Shield,
};

const reportTypeFilterOptions: { value: ReportTypeFilter; label: string }[] = [
  { value: "all", label: "All Report Type" },
  ...reportTypes.map((type) => ({
    value: type.id as ReportTypeFilter,
    label: type.typeLabel,
  })),
];

const reportStatusFilterOptions: {
  value: ReportStatusFilter;
  label: string;
}[] = [
  { value: "all", label: "All Status" },
  { value: "completed", label: "Completed" },
  { value: "processing", label: "Processing" },
];

export function ReportsContent() {
  const [typeFilter, setTypeFilter] = useState<ReportTypeFilter>("all");
  const [statusFilter, setStatusFilter] = useState<ReportStatusFilter>("all");
  const [dateRange, setDateRange] = useState<DateRange>("last-7-days");
  const [filtersOpen, setFiltersOpen] = useState(false);

  const filteredReports = useMemo(() => {
    return generatedReports.filter((report) => {
      const matchesType =
        typeFilter === "all" ? true : report.type === typeFilter;
      const matchesStatus =
        statusFilter === "all" ? true : report.status === statusFilter;
      return matchesType && matchesStatus;
    });
  }, [typeFilter, statusFilter]);

  const typeFilterLabel =
    reportTypeFilterOptions.find((option) => option.value === typeFilter)
      ?.label ?? "All Report Type";
  const statusFilterLabel =
    reportStatusFilterOptions.find((option) => option.value === statusFilter)
      ?.label ?? "All Status";
  const dateRangeLabel =
    dateRangeOptions.find((option) => option.value === dateRange)?.label ??
    "Last 7 Days";

  const typeFilterControl = (
    <DropdownMenu>
      <DropdownMenuTrigger
        type="button"
        className={buttonVariants({
          variant: "secondary",
          className: "h-10 w-full justify-between gap-1 px-3 md:h-8 md:w-auto",
        })}
      >
        <span className="truncate">{typeFilterLabel}</span>
        <ChevronDownIcon className="size-5 shrink-0" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        collisionPadding={16}
        className="astrix-dashboard min-w-44"
      >
        <DropdownMenuRadioGroup
          value={typeFilter}
          onValueChange={(value) => setTypeFilter(value as ReportTypeFilter)}
        >
          {reportTypeFilterOptions.map((option) => (
            <DropdownMenuRadioItem
              key={option.value}
              value={option.value}
              className="font-normal text-muted-foreground data-[state=checked]:font-medium data-[state=checked]:text-foreground"
            >
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );

  const statusFilterControl = (
    <DropdownMenu>
      <DropdownMenuTrigger
        type="button"
        className={buttonVariants({
          variant: "secondary",
          className: "h-10 w-full justify-between gap-1 px-3 md:h-8 md:w-auto",
        })}
      >
        <span className="truncate">{statusFilterLabel}</span>
        <ChevronDownIcon className="size-5 shrink-0" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        collisionPadding={16}
        className="astrix-dashboard min-w-40"
      >
        <DropdownMenuRadioGroup
          value={statusFilter}
          onValueChange={(value) =>
            setStatusFilter(value as ReportStatusFilter)
          }
        >
          {reportStatusFilterOptions.map((option) => (
            <DropdownMenuRadioItem
              key={option.value}
              value={option.value}
              className="font-normal text-muted-foreground data-[state=checked]:font-medium data-[state=checked]:text-foreground"
            >
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );

  const dateFilterControl = (
    <DropdownMenu>
      <DropdownMenuTrigger
        type="button"
        className={buttonVariants({
          variant: "secondary",
          className: "h-10 min-w-0 justify-between gap-2 px-3 md:h-8 md:w-auto",
        })}
      >
        <span className="flex min-w-0 items-center gap-2">
          <Calendar className="size-5 shrink-0" />
          <span className="truncate">{dateRangeLabel}</span>
        </span>
        <ChevronDownIcon className="size-5 shrink-0" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        collisionPadding={16}
        className="astrix-dashboard min-w-40"
      >
        <DropdownMenuRadioGroup
          value={dateRange}
          onValueChange={(value) => setDateRange(value as DateRange)}
        >
          {dateRangeOptions.map((option) => (
            <DropdownMenuRadioItem
              key={option.value}
              value={option.value}
              className="font-normal text-muted-foreground data-[state=checked]:font-medium data-[state=checked]:text-foreground"
            >
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );

  return (
    <div className="mx-auto flex w-full max-w-7xl flex-col gap-10 px-4 pt-8 pb-10 md:px-6">
      <div className="space-y-2">
        <h1 className="text-2xl font-semibold">Compliance Reports</h1>
        <p className="text-lg text-muted-foreground">
          Generate and manage regulatory compliance documentation
        </p>
      </div>

      <section className="flex flex-col gap-4">
        <h2 className="text-lg font-medium">
          Select a report type to generate compliance documentation
        </h2>

        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {reportTypes.map((type) => {
            const Icon = reportTypeIcons[type.id];

            return (
              <div
                key={type.id}
                className="flex flex-col gap-8 rounded-xl border p-4 pb-3.5"
              >
                <div className="flex size-11 items-center justify-center rounded-lg bg-secondary">
                  <Icon className="size-5" />
                </div>

                <div className="flex flex-1 flex-col gap-4">
                  <div className="space-y-1">
                    <p className="text-sm font-semibold">{type.title}</p>
                    <p className="text-xs text-muted-foreground">
                      {type.description}
                    </p>
                  </div>

                  <Button
                    type="button"
                    variant="secondary"
                    className="h-10 w-full gap-2"
                  >
                    Generate Report
                    <ArrowRight className="size-4.5" />
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </section>

      <section className="flex flex-col gap-5">
        <div className="flex flex-col gap-4 md:hidden">
          <div className="space-y-2">
            <h2 className="text-lg font-medium">Generated Reports</h2>
            <p className="text-sm text-muted-foreground">
              Download and manage compliance documentation
            </p>
          </div>

          <div className="flex items-center gap-2">
            <div className="min-w-0 flex-1">{dateFilterControl}</div>

            <Button
              type="button"
              variant="outline"
              className="h-10 shrink-0 gap-2 px-3"
              aria-expanded={filtersOpen}
              onClick={() => setFiltersOpen((open) => !open)}
            >
              <span className="flex items-center gap-2">
                <ListFilter className="size-5 shrink-0" />
                Filters
              </span>
              <ChevronDownIcon
                className={cn(
                  "size-5 shrink-0 transition-transform",
                  filtersOpen && "rotate-180",
                )}
              />
            </Button>
          </div>

          {filtersOpen ? (
            <div className="flex flex-col gap-2 min-[380px]:flex-row">
              <div className="min-w-0 flex-1">{typeFilterControl}</div>
              <div className="min-w-0 flex-1">{statusFilterControl}</div>
            </div>
          ) : null}
        </div>

        <div className="@container/reports-header hidden w-full min-w-0 md:block">
          <div className="flex w-full min-w-0 flex-col gap-4 @min-[52rem]/reports-header:flex-row @min-[52rem]/reports-header:items-end @min-[52rem]/reports-header:justify-between">
            <div className="min-w-0 space-y-2 @min-[52rem]/reports-header:min-w-56">
              <h2 className="text-lg font-medium">Generated Reports</h2>
              <p className="text-sm text-muted-foreground">
                Download and manage compliance documentation
              </p>
            </div>

            <div className="flex w-full min-w-0 items-center justify-between gap-2 @min-[52rem]/reports-header:w-auto">
              {dateFilterControl}
              <div className="flex items-center gap-2">
                {typeFilterControl}
                {statusFilterControl}
              </div>
            </div>
          </div>
        </div>

        <Table className="min-w-215">
          <colgroup>
            <col className="w-[36%]" />
            <col className="w-[16%]" />
            <col className="w-[16%]" />
            <col className="w-[16%]" />
            <col className="w-[16%]" />
          </colgroup>
          <TableHeader>
            <TableRow>
              <TableHead>Report Name</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Date Generated</TableHead>
              <TableHead>Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredReports.map((report) => (
              <ReportRowItem key={report.id} report={report} />
            ))}
          </TableBody>
        </Table>
      </section>
    </div>
  );
}

function ReportRowItem({ report }: { report: GeneratedReport }) {
  const canDownload = report.status === "completed";

  return (
    <TableRow>
      <TableCell className="whitespace-normal">
        <div className="space-y-1">
          <p className="font-medium">{report.name}</p>
          <p className="text-sm text-muted-foreground">{report.id}</p>
        </div>
      </TableCell>
      <TableCell>{report.typeLabel}</TableCell>
      <TableCell>
        <ReportStatusBadge status={report.status} />
      </TableCell>
      <TableCell className="text-muted-foreground">
        {report.generated}
      </TableCell>
      <TableCell>
        <Button
          type="button"
          variant="ghost"
          size="lg"
          disabled={!canDownload}
          className="gap-2"
        >
          Download
          <FolderDown className="size-5" />
        </Button>
      </TableCell>
    </TableRow>
  );
}

import { Clock } from "lucide-react";
import { CheckCircleIcon, WarningCircleIcon } from "./icons";
import type { ClassificationStatus, ReportStatus } from "../../data";

const classificationStatusConfig = {
  approved: {
    label: "Approved",
    className: "bg-success/10 text-success",
    icon: CheckCircleIcon,
